"""Give already-rendered transparent previews an opaque viewing background."""
import concurrent.futures
import json
import time
from PIL import Image
from hero_animation import HEROES, OUT, write

def one(path):
    try:
        # A completed still PNG is written after the animated file. Wait a
        # little longer before touching a preview generated by another job.
        if not path.with_suffix('.png').exists() or time.time() - path.stat().st_mtime < 15:
            return {'file': str(path.relative_to(OUT)), 'status': 'pending'}
        frames = []
        durations = []
        has_alpha = False
        with Image.open(path) as image:
            if image.mode == 'RGB':
                return {'file': str(path.relative_to(OUT)), 'status': 'already_opaque'}
            for i in range(image.n_frames):
                image.seek(i)
                frame = image.convert('RGBA')
                has_alpha |= frame.getchannel('A').getextrema()[0] < 255
                background = Image.new('RGBA', frame.size, (32, 37, 48, 255))
                background.alpha_composite(frame)
                frames.append(background.convert('RGB'))
                durations.append(image.info.get('duration', 0))
        if not has_alpha:
            return {'file': str(path.relative_to(OUT)), 'status': 'already_opaque'}
        temporary = path.with_name(path.name + '.opaque.tmp')
        frames[0].save(temporary, format='WEBP', save_all=True, append_images=frames[1:],
                       duration=durations, lossless=True, method=1, loop=0)
        duration = 0
        with Image.open(temporary) as image:
            for i in range(image.n_frames):
                image.seek(i)
                image.load()
                if image.convert('RGBA').getchannel('A').getextrema() != (255, 255):
                    raise ValueError('Preview is not opaque')
                duration += image.info.get('duration', 0)
            if image.n_frames > 1 and duration != sum(durations):
                raise ValueError('Preview duration changed')
        temporary.replace(path)
        return {'file': str(path.relative_to(OUT)), 'status': 'converted',
                'duration_ms': duration, 'encoded_frames': len(frames)}
    except Exception as exc:
        return {'file': str(path.relative_to(OUT)), 'status': 'error', 'error': str(exc)}

if __name__ == '__main__':
    paths = sorted(HEROES.glob('*/previews/*.webp'))
    records = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        for record in pool.map(one, paths):
            records.append(record)
            if len(records) % 25 == 0 or record['status'] == 'error':
                print(f'Opaque previews {len(records)}/{len(paths)}: {record["status"]}', flush=True)
    write(OUT / 'reports/hero_preview_backgrounds.json', json.dumps(records, ensure_ascii=False, indent=2).encode())
    print('Preview backgrounds complete', len(records), flush=True)
